<?php require 'includes/auth.php';if(user())redirect(user()['role'].'/dashboard.php');$errors=[];$role=$_GET['role']??'buyer';if(!in_array($role,['buyer','seller']))$role='buyer';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$role=post('role');$name=post('name');$email=filter_var(post('email'),FILTER_VALIDATE_EMAIL);$phone=post('phone');$pass=$_POST['password']??'';$shop=post('shop_name');if(!in_array($role,['buyer','seller']))$errors[]='Choose a valid account type.';if(strlen($name)<2)$errors[]='Enter your name.';if(!$email)$errors[]='Enter a valid email.';if(strlen($pass)<8)$errors[]='Password must contain at least 8 characters.';if($role==='seller'&&strlen($shop)<2)$errors[]='Enter your shop name.';if(!$errors){try{$pdo=db();$pdo->beginTransaction();$pdo->prepare('INSERT INTO users(name,email,password_hash,role,phone) VALUES(?,?,?,?,?)')->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role,$phone]);$uid=$pdo->lastInsertId();if($role==='seller')$pdo->prepare('INSERT INTO seller_profiles(user_id,shop_name,description,location) VALUES(?,?,?,?)')->execute([$uid,$shop,post('description'),post('location')]);$pdo->commit();flash('success',$role==='seller'?'Registration received. An administrator must approve your shop before selling.':'Account created. Please sign in.');redirect('login.php');}catch(PDOException $e){if(db()->inTransaction())db()->rollBack();$errors[]=$e->getCode()==='23000'?'That email is already registered.':'Could not create account. Please retry.';}}}$pageTitle='Create account';require 'includes/header.php';?><div class="auth"><div><p class="eyebrow">JOIN THE MARKETPLACE</p><h1>Good seafood starts here.</h1><p>Buy today’s catch or become a trusted local seller.</p></div><form method="post" class="card-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><?php foreach($errors as $e):?><p class="field-error"><?=e($e)?></p><?php endforeach;?><label>I want to<select name="role" id="role-select"><option value="buyer" <?=$role==='buyer'?'selected':''?>>Buy fresh fish</option><option value="seller" <?=$role==='seller'?'selected':''?>>Sell seafood</option></select></label><label>Full name<input name="name" value="<?=e(post('name'))?>" required></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone" value="<?=e(post('phone'))?>"></label><label>Password<input type="password" name="password" minlength="8" required></label><div class="seller-fields"><label>Shop name<input name="shop_name" value="<?=e(post('shop_name'))?>"></label><label>Location<input name="location" value="<?=e(post('location'))?>"></label><label>About your shop<textarea name="description"><?=e(post('description'))?></textarea></label></div><button>Create account</button><p>Already a member? <a href="login.php">Sign in</a></p></form></div><?php require 'includes/footer.php'; ?>
